/**
 * S75/task 3: report quality. The parts that must not contradict the numbers are generated by code
 * from the vector and from the chain; the model only writes prose.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { createEvidenceStore } from "../src/core/evidence.ts";
import { createFindingsStore } from "../src/core/findings.ts";
import { deriveConditions, extractEvidence, redactExtract, renderReport, validateReport, validateReportText } from "../src/core/report.ts";
import { signExecution } from "../src/core/attestation.ts";
import { parseGlobalConfig } from "../src/core/config.ts";
import { createSession } from "../src/pi/session.ts";

const METRICS = { AV: "N", AC: "L", AT: "N", PR: "N", UI: "N", VC: "H", VI: "N", VA: "N", SC: "N", SI: "N", SA: "N" };
const VECTOR = `CVSS:4.0/${Object.entries(METRICS).map(([key, value]) => `${key}:${value}`).join("/")}`;

async function buildChain(dir: string, options: { signature?: string } = {}) {
	const store = createEvidenceStore(join(dir, "work", "lab", "evidence"), { now: () => Date.now() });
	const at1 = "2026-01-02T10:00:00.000Z";
	await store.append({ kind: "execution", payload: { tool: "curl", argv: ["curl", "-sS", "http://127.0.0.1:3000/api/invoices/2"], endpoint: "/api/invoices/2", at: at1, sessionId: "main" } });
	await store.append({ kind: "execution-result", payload: { tool: "curl", exitCode: 0, stdout: "HTTP/1.1 200 OK\n{\"id\":2,\"email\":\"victim@example.com\",\"card\":\"4111 1111 1111 1111\"}", stderr: "" } });
	const at3 = "2026-01-02T10:05:00.000Z";
	const argv = ["curl", "-sS", "-H", "Cookie: session=abc123secret", "-w", "\\n%{http_code}", "http://127.0.0.1:3000/api/invoices/2"];
	const signature = signExecution(options.signature ?? "tok-1", { sessionId: "child-1", tool: "curl", argv, endpoint: "/api/invoices/2", at: at3 });
	await store.append({ kind: "execution", payload: { tool: "curl", argv, endpoint: "/api/invoices/2", at: at3, sessionId: "child-1", signature } });
	await store.append({ kind: "execution-result", payload: { tool: "curl", exitCode: 0, stdout: "{\"id\":2,\"email\":\"victim@example.com\"}\n200", stderr: "" } });
	await store.append({ kind: "verification", payload: { event: "verified", finding: "F-0001", verdict: "REPRODUCIDO", seqs: [3], at: "2026-01-02T10:06:00.000Z", sessionId: "main" } });
	return store;
}

async function setup(lang: "en" | "es" = "es", redact = true) {
	const dir = await mkdtemp(join(tmpdir(), "bounty-report-"));
	await mkdir(join(dir, "work", "lab"), { recursive: true });
	const scopePath = join(dir, "scope.yaml");
	await writeFile(scopePath, "program: lab\nlab: true\nauthorized_on: 2026-01-01\nin_scope:\n  - 127.0.0.1:3000\nlimits:\n  rate_rps: 5\n", "utf8");
	const session = createSession(
		{ root: dir, program: "lab", reportLang: lang, reportRedact: redact },
		{ dns: async () => ({ cname: [] }), readFile: (path) => readFile(path, "utf8"), runTool: async () => ({ exitCode: 0, stdout: "", stderr: "" }), confirm: async () => true },
	);
	await session.scope({ file: scopePath });
	const findings = createFindingsStore({ dir: join(dir, "work", "lab", "findings"), program: "lab" });
	const created = await findings.create({ title: "IDOR en facturas del lab", class: "idor", endpoint: "/api/invoices/2", parameter: "id" });
	await findings.update(created.finding.id, { state: "verified" }, "veredicto del verificador");
	return { dir, session, findingId: created.finding.id, cleanup: () => rm(dir, { recursive: true, force: true }) };
}

test("(a) the summary cannot be the title again and needs two sentences", async () => {
	const h = await setup();
	try {
		await buildChain(h.dir);
		const same = await h.session.report({ findingId: h.findingId, metrics: METRICS, summary: "IDOR en facturas del lab", impact: "x", remediation: "y" });
		assert.equal(same.ok, false);
		assert.match(same.text, /no puede ser igual al título/);
		const short = await h.session.report({ findingId: h.findingId, metrics: METRICS, summary: "Un IDOR en el lab.", impact: "x", remediation: "y" });
		assert.equal(short.ok, false);
		assert.match(short.text, /dos frases/);
		const good = await h.session.report({
			findingId: h.findingId,
			metrics: METRICS,
			summary: "Un IDOR en el lab permite leer facturas ajenas. El verificador lo reprodujo dos veces.",
			steps: ["GET /api/invoices/2"],
			impact: "Lectura de facturas ajenas.",
			remediation: "Validar propiedad.",
		});
		assert.equal(good.ok, true, good.text);
	} finally {
		await h.cleanup();
	}
});

test("(b) prerequisites come from the vector, and prose that contradicts it is flagged", () => {
	const conditions = deriveConditions(VECTOR, "es").map((item) => item.text).join(" ");
	assert.match(conditions, /No requiere credenciales/);
	assert.doesNotMatch(conditions, /privilegios altos/);
	const contradicting = validateReportText({ title: "t", summary: "Uno. Dos.", impact: "Un usuario autenticado lee facturas.", vector: VECTOR, lang: "es" });
	assert.equal(contradicting.ok, true);
	assert.equal(contradicting.warnings.length, 1);
	assert.match(contradicting.warnings[0] as string, /PR:N/);
	const prHigh = VECTOR.replace("PR:N", "PR:H");
	assert.match(deriveConditions(prHigh, "es").map((item) => item.text).join(" "), /privilegios altos/);
});

test("(c)(e) evidence is extracted from the chain, with signatures, expected and omitted seqs", async () => {
	const h = await setup();
	try {
		await buildChain(h.dir);
		const report = await h.session.report({
			findingId: h.findingId,
			metrics: METRICS,
			summary: "Un IDOR en el lab permite leer facturas ajenas. El verificador lo reprodujo dos veces.",
			steps: ["Abrir la factura 2 con la sesión propia."],
			impact: "Lectura de facturas ajenas.",
			remediation: "Validar propiedad.",
			cwe: "CWE-639",
			sensitiveData: "Facturas con email de terceros",
		});
		assert.equal(report.ok, true, report.text);
		const markdown = await readFile(join(h.dir, "work", "lab", "reports", `${h.findingId}.md`), "utf8");
		assert.match(markdown, /## Condiciones previas/);
		assert.match(markdown, /No requiere credenciales/);
		assert.match(markdown, /CWE-639/);
		assert.match(markdown, /Dato sensible expuesto/);
		assert.match(markdown, /Hallazgo inicial \(seq 1\)/);
		assert.match(markdown, /Reproducción del verificador/);
		assert.match(markdown, /seq 3.*firma válida/s);
		assert.match(markdown, /GET http:\/\/127\.0\.0\.1:3000\/api\/invoices\/2/);
		assert.match(markdown, /estado: 200/);
		assert.match(markdown, /Sin documentar/);
		assert.match(markdown, /veredicto en seq 5/);
		assert.match(markdown, /Esperado: Abrir la factura 2/);
	} finally {
		await h.cleanup();
	}
});

test("(d) redaction is on by default in the report and does not touch the model view", () => {
	const raw = [
		"Cookie: session=abc123",
		"Authorization: Bearer eyJhbGciOiJIUzI1NiJ9.x.y",
		"key sk_live_abcdef123456",
		"email victim@example.com",
		"card 4111 1111 1111 1111",
	].join("\n");
	const masked = redactExtract(raw, true);
	assert.doesNotMatch(masked, /abc123/);
	assert.doesNotMatch(masked, /eyJhbGciOiJIUzI1NiJ9/);
	assert.doesNotMatch(masked, /sk_live_abcdef123456/);
	assert.doesNotMatch(masked, /victim@example\.com/);
	assert.doesNotMatch(masked, /4111 1111 1111 1111/);
	assert.match(masked, /\[redactado\]/);
	assert.match(masked, /\[redactado\]@example\.com/);
	assert.equal(redactExtract(raw, false), raw);
});

test("(f) report_lang defaults to en and accepts es; the report follows it", async () => {
	const parsed = parseGlobalConfig("{}");
	assert.equal(parsed.ok && parsed.config.reportLang, "en");
	assert.equal(parsed.ok && parsed.config.reportRedact, true);
	const es = parseGlobalConfig('{"report_lang":"es","report_redact":false}');
	assert.equal(es.ok && es.config.reportLang, "es");
	assert.equal(es.ok && es.config.reportRedact, false);
	const bad = parseGlobalConfig('{"report_lang":"fr"}');
	assert.equal(bad.ok, false);
	const h = await setup("en");
	try {
		await buildChain(h.dir);
		await h.session.report({
			findingId: h.findingId,
			metrics: METRICS,
			summary: "An IDOR lets a user read other invoices. The verifier reproduced it twice.",
			steps: ["GET /api/invoices/2"],
			impact: "Read access.",
			remediation: "Check ownership.",
		});
		const markdown = await readFile(join(h.dir, "work", "lab", "reports", `${h.findingId}.md`), "utf8");
		assert.match(markdown, /## Prerequisites/);
		assert.match(markdown, /## Evidence/);
		assert.doesNotMatch(markdown, /## Condiciones previas/);
		assert.equal(validateReport(markdown, "en").ok, true);
		assert.equal(validateReport(markdown, "es").ok, false);
	} finally {
		await h.cleanup();
	}
});

test("the evidence extractor pairs executions with their results and truncates long bodies", () => {
	const records = [
		{ seq: 1, kind: "execution", ts: "t", hash: "a".repeat(64), payload: { tool: "curl", argv: ["curl", "http://127.0.0.1:3000/x"], endpoint: "/x" } },
		{ seq: 2, kind: "execution-result", ts: "t", hash: "b".repeat(64), payload: { tool: "curl", exitCode: 0, stdout: `${"A".repeat(400)}\n200`, stderr: "" } },
	] as never[];
	const extracted = extractEvidence(records as never, { reproSeqs: [1], initialSeq: null, redact: true, lang: "es" });
	assert.equal(extracted.reproduction.length, 1);
	assert.equal(extracted.reproduction[0]?.status, "200");
	assert.match(extracted.reproduction[0]?.body ?? "", /recortado/);
	assert.equal(extracted.reproduction[0]?.signed, false);
});


test("(S76/5) redaction covers the reporter's prose, not just the extracts", async () => {
	const prose = "La sesión viaja en Cookie: session=abc123 y el token es Bearer eyJhbGciOiJIUzI1NiJ9.x.y; la tarjeta 4111 1111 1111 1111 y el email victim@example.com aparecen en la respuesta.";
	const h = await setup("es", true);
	try {
		await buildChain(h.dir);
		const written = await h.session.report({
			findingId: h.findingId,
			metrics: METRICS,
			summary: `${prose} El verificador lo reprodujo dos veces.`,
			steps: [`GET /api/invoices/2 con ${prose}`],
			impact: prose,
			remediation: prose,
		});
		assert.equal(written.ok, true, written.text);
		const markdown = await readFile(join(h.dir, "work", "lab", "reports", `${h.findingId}.md`), "utf8");
		for (const secret of ["abc123", "eyJhbGciOiJIUzI1NiJ9", "4111 1111 1111 1111", "victim@example.com"]) {
			assert.ok(!markdown.includes(secret), `the report still contains ${secret}`);
		}
		assert.match(markdown, /\[redactado\]/);
	} finally {
		await h.cleanup();
	}
});

test("(S76/5) with report_redact off the prose is kept as written", async () => {
	const secret = "Cookie: session=abc123";
	const h = await setup("es", false);
	try {
		await buildChain(h.dir);
		const written = await h.session.report({
			findingId: h.findingId,
			metrics: METRICS,
			summary: `La sesión viaja en ${secret}. El verificador lo reprodujo dos veces.`,
			steps: ["GET /api/invoices/2"],
			impact: "Lectura de facturas ajenas.",
			remediation: "Validar propiedad.",
		});
		assert.equal(written.ok, true, written.text);
		const markdown = await readFile(join(h.dir, "work", "lab", "reports", `${h.findingId}.md`), "utf8");
		assert.match(markdown, /session=abc123/);
	} finally {
		await h.cleanup();
	}
});
